CREATE TABLE "MovimientosKardex" (
                                     "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
                                     "ProductoId" integer NOT NULL,
                                     "AlmacenId" integer NOT NULL,
                                     "LoteId" integer,
                                     "Fecha" timestamp with time zone NOT NULL,
                                     "Tipo" character varying(10) NOT NULL,
                                     "Cantidad" integer NOT NULL,
                                     "CostoUnitario" numeric(18,4),
                                     "Referencia" character varying(100),
                                     CONSTRAINT "PK_MovimientosKardex" PRIMARY KEY ("Id"),
                                     CONSTRAINT "FK_MovimientosKardex_Productos_ProductoId" FOREIGN KEY ("ProductoId") REFERENCES "Productos" ("Id") ON DELETE RESTRICT,
                                     CONSTRAINT "FK_MovimientosKardex_Almacenes_AlmacenId" FOREIGN KEY ("AlmacenId") REFERENCES "Almacenes" ("Id") ON DELETE RESTRICT,
                                     CONSTRAINT "FK_MovimientosKardex_Lotes_LoteId" FOREIGN KEY ("LoteId") REFERENCES "Lotes" ("Id") ON DELETE RESTRICT,
                                     CONSTRAINT "CK_MovimientosKardex_Tipo" CHECK ("Tipo" IN ('Entrada', 'Salida')),
                                     CONSTRAINT "CK_MovimientosKardex_Cantidad" CHECK ("Cantidad" BETWEEN 1 AND 1000000),
                                     CONSTRAINT "CK_MovimientosKardex_Costo" CHECK (
                                         ("Tipo" = 'Entrada' AND "CostoUnitario" IS NOT NULL AND "CostoUnitario" > 0)
                                             OR ("Tipo" = 'Salida' AND "CostoUnitario" IS NULL))
);

CREATE INDEX "IX_MovimientosKardex_ProductoId_AlmacenId_Fecha" ON "MovimientosKardex" ("ProductoId", "AlmacenId", "Fecha");
CREATE INDEX "IX_MovimientosKardex_AlmacenId" ON "MovimientosKardex" ("AlmacenId");
CREATE INDEX "IX_MovimientosKardex_LoteId" ON "MovimientosKardex" ("LoteId");